/* screenprint-fast-quote.css — extracted 2026-09-06 from the inline \3c style> in quote-builders/screenprint-fast-quote.html (Rule 3). */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
/* stylelint-enable color-no-hex */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background: linear-gradient(135deg, var(--color-bradley-tint) 0%, var(--gray-300) 100%);
    min-height: 100vh;
    padding: 20px;
}

.container {
    max-width: 600px;
    margin: 0 auto;
    background: white;
    border-radius: 16px;
    box-shadow: 0 10px 40px rgb(0 0 0 / 10%);
    overflow: hidden;
}

/* Header */
.header {
    background: linear-gradient(135deg, var(--brand-mid) 0%, var(--print-green) 100%);
    color: white;
    padding: 30px;
    text-align: center;
}

.header h1 {
    font-size: 28px;
    margin-bottom: 10px;
}

.header p {
    font-size: 16px;
    opacity: 0.9;
}

/* Progress Indicator */
.progress-bar {
    display: flex;
    justify-content: space-between;
    padding: 20px 30px;
    background: var(--gray-50);
    border-bottom: 1px solid var(--gray-200);
}

.progress-step {
    flex: 1;
    text-align: center;
    position: relative;
}

.progress-step:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 15px;
    right: -50%;
    width: 100%;
    height: 2px;
    background: var(--gray-200);
    z-index: 0;
}

.progress-step.active:not(:last-child)::after {
    background: var(--brand-mid);
}

.progress-circle {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: var(--gray-200);
    color: var(--gray-500);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 14px;
    position: relative;
    z-index: 1;
    transition: all 0.3s;
}

.progress-step.active .progress-circle {
    background: var(--brand-mid);
    color: white;
    transform: scale(1.1);
}

.progress-step.completed .progress-circle {
    background: var(--bs-success);
    color: white;
}

.progress-label {
    display: block;
    margin-top: 8px;
    font-size: 12px;
    color: var(--gray-500);
}

.progress-step.active .progress-label {
    color: var(--brand-mid);
    font-weight: 600;
}

/* Content Area */
.content {
    padding: 40px 30px;
}

.step {
    display: none;
}

.step.active {
    display: block;
    animation: fadeIn 0.3s;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

.step-title {
    font-size: 24px;
    color: var(--gray-700);
    margin-bottom: 10px;
}

.step-subtitle {
    font-size: 14px;
    color: var(--slate-500);
    margin-bottom: 30px;
}

/* Form Elements */
.form-group {
    margin-bottom: 20px;
}

.form-label {
    display: block;
    font-size: 14px;
    font-weight: 600;
    color: var(--gray-700);
    margin-bottom: 8px;
}

.form-input,
.form-select {
    width: 100%;
    padding: 12px 16px;
    border: 2px solid var(--slate-200);
    border-radius: 8px;
    font-size: 15px;
    transition: all 0.2s;
}

.form-input:focus,
.form-select:focus {
    outline: none;
    border-color: var(--brand-mid);
    box-shadow: 0 0 0 3px rgb(58 124 82 / 10%);
}

.form-textarea {
    width: 100%;
    padding: 12px 16px;
    border: 2px solid var(--slate-200);
    border-radius: 8px;
    font-size: 15px;
    min-height: 100px;
    resize: vertical;
    font-family: inherit;
}

/* Option Cards */
.option-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.option-card {
    padding: 20px;
    border: 2px solid var(--slate-200);
    border-radius: 12px;
    cursor: pointer;
    text-align: center;
    transition: all 0.2s;
}

.option-card:hover {
    border-color: var(--brand-mid);
    background: var(--brand-50);
    transform: translateY(-2px);
}

.option-card.selected {
    border-color: var(--brand-mid);
    background: linear-gradient(135deg, var(--brand-100) 0%, var(--gray-100) 100%);
    box-shadow: 0 4px 12px rgb(58 124 82 / 20%);
}

.option-card-icon {
    font-size: 32px;
    margin-bottom: 10px;
    color: var(--brand-mid);
}

.option-card-label {
    font-size: 15px;
    font-weight: 600;
    color: var(--gray-700);
}

.option-card-hint {
    font-size: 12px;
    color: var(--slate-500);
    margin-top: 5px;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 15px;
    margin-top: 30px;
}

.btn {
    flex: 1;
    padding: 14px 24px;
    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: linear-gradient(135deg, var(--brand-mid) 0%, var(--print-green) 100%);
    color: white;
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgb(58 124 82 / 30%);
}

.btn-secondary {
    background: var(--slate-200);
    color: var(--slate-600);
}

.btn-secondary:hover {
    background: var(--gray-300);
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    transform: none !important;
}

/* Success Screen */
.success-icon {
    text-align: center;
    font-size: 64px;
    color: var(--bs-success);
    margin-bottom: 20px;
}

.success-message {
    text-align: center;
}

.success-message h2 {
    font-size: 28px;
    color: var(--gray-700);
    margin-bottom: 10px;
}

.success-message p {
    font-size: 16px;
    color: var(--slate-500);
    line-height: 1.6;
}

.quote-id-display {
    background: var(--slate-50);
    border: 2px solid var(--brand-mid);
    border-radius: 12px;
    padding: 20px;
    margin: 30px 0;
    text-align: center;
}

.quote-id-label {
    font-size: 14px;
    color: var(--slate-500);
    margin-bottom: 5px;
}

.quote-id-value {
    font-size: 32px;
    font-weight: 700;
    color: var(--brand-mid);
}

/* Estimate Display */
.estimate-box {
    background: linear-gradient(135deg, var(--brand-100) 0%, var(--gray-100) 100%);
    border: 2px solid var(--brand-mid);
    border-radius: 12px;
    padding: 25px;
    margin: 30px 0;
}

.estimate-label {
    font-size: 14px;
    color: var(--print-green);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 10px;
}

.estimate-range {
    font-size: 36px;
    font-weight: 700;
    color: var(--brand-mid);
    margin-bottom: 10px;
}

.estimate-note {
    font-size: 13px;
    color: var(--slate-600);
    line-height: 1.5;
}

/* Responsive */
@media (width <= 640px) {
    .container {
        border-radius: 0;
    }

    .content {
        padding: 30px 20px;
    }

    .option-cards {
        grid-template-columns: 1fr;
    }

    .button-group {
        flex-direction: column;
    }

    .header h1 {
        font-size: 24px;
    }
}

/* 2026-09-06 review */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }
.fq-thanks-list { text-align: left; margin: 20px 0; padding-left: 40px; color: var(--slate-600); }
.fq-mt-30 { margin-top: 30px; }

