            color: #2e5827;
            margin-bottom: 5px;
        }

        .quote-details {
            font-size: 10px;
            color: #666;
        }

        .quote-details strong {
            color: #333;
        }

        /* Customer Section */
        .customer-section {
            display: flex;
            justify-content: space-between;
            margin-bottom: 8px;
            padding: 6px;
            background: #f8f9fa;
            border-radius: 3px;
        }

        .customer-info, .sales-rep-info {
            flex: 1;
        }

        .section-title {
            font-size: 11px;
            font-weight: bold;
            color: #2e5827;
            margin-bottom: 3px;
        }

        .info-line {
            font-size: 10px;
            color: #666;
            margin: 1px 0;
        }

        /* Products Table */
        .products-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 15px;
        }

        .products-table thead {
            background: #2e5827;
            color: white;
        }

        .products-table th {
            padding: 5px 4px;
            text-align: left;
            font-size: 10px;
            font-weight: 600;
            border-right: 1px solid rgba(255,255,255,0.2);
        }

        .products-table th:last-child {
            border-right: none;
        }

        .products-table th:nth-child(6) {
            text-align: center;
        }

        .products-table th:nth-child(7),
        .products-table th:nth-child(8) {
            text-align: right;
        }

        .products-table td {
            padding: 3px;
            border-bottom: 1px solid #e0e0e0;
            font-size: 10.5px;   /* was 9px — receipt-sized on the artifact customers forward (expert audit 2026-07-07) */
            vertical-align: top;
        }

        .price-breakdown {
            font-size: 10px;
            line-height: 1.3;
            color: #666;
        }

        .price-total {
            font-weight: bold;
            color: #000;
            border-top: 1px solid #ddd;
            margin-top: 2px;
            padding-top: 2px;
        }

        .product-image {
            width: 20px;
            height: 20px;
            object-fit: contain;
            display: block;
        }

        .description-cell {
            line-height: 1.3;
        }

        .logo-position {
            font-weight: 600;
            color: #333;
        }

        .stitch-count {
            font-size: 10px;
            color: #666;
            display: inline;
            margin-left: 3px;
        }

        .size-breakdown {
            font-family: 'Courier New', monospace;
            font-size: 10px;
            word-break: break-word;
            line-height: 1.2;
        }

        /* Additional Services */
        .additional-service-row {
            background: #f8f9fa;
        }

        /* Totals Section */
        .totals-section {
            margin-left: auto;
            width: 300px;
            margin-top: 20px;
        }

        .total-row {
            display: flex;
            justify-content: space-between;
            padding: 5px 0;
            font-size: 13px;
        }

        .total-row.subtotal-row {
            border-top: 1px solid #e0e0e0;
            padding-top: 10px;
        }

        .total-row.tax-row {
            color: #666;
        }

        .total-row.grand-total {   /* the number the customer is looking for */
            border-top: 2px solid #2e5827;
            padding-top: 10px;
            margin-top: 5px;
            font-size: 18px;
            font-weight: bold;
            color: #2e5827;
        }

        /* Footer */
        .invoice-footer {
            margin-top: 40px;
            padding-top: 20px;
            border-top: 1px solid #e0e0e0;
        }

        .footer-section {
            margin-bottom: 15px;
        }

        .footer-title {
            font-size: 12px;
            font-weight: bold;
            color: #2e5827;
            margin-bottom: 5px;
        }

        .footer-text {
            font-size: 11px;
            color: #666;
            line-height: 1.4;
        }

        .tagline {
            text-align: center;
            font-style: italic;
            color: #999;
            margin-top: 20px;
            font-size: 11px;
        }

        @media print {
            body {
                margin: 0;
                line-height: 1.3;
            }
            .invoice-container {
                padding: 0;
            }
            .products-table tr {
                page-break-inside: avoid;
            }
            .no-print {
                display: none;
            }
            /* Single-page fit: the on-screen invoice fits one page, but the
               PDF overflowed to a 2nd page once the method specs/locations
               box was added. Compact the print spacing (screen view unchanged).
               Erik 2026-06-02. */
            .invoice-header { margin-bottom: 6px; }
            .method-specs { margin: 5px 0 !important; padding: 6px 8px !important; }
            .totals-section { margin-top: 8px; }
            .invoice-footer { margin-top: 12px; padding-top: 8px; page-break-inside: avoid; }
            .footer-section { margin-bottom: 5px; }
            .tagline { margin-top: 8px; }
        }

        /* Size Matrix Table */
        .size-matrix {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 10px;
        }
        .size-matrix th {
            background: #2e5827;
            color: white;
            padding: 5px 3px;
            font-size: 10px;
            text-align: center;
            font-weight: 600;
        }
        .size-matrix th.part-col,
        .size-matrix th.color-col {
            text-align: left;
            padding-left: 6px;
        }
        .size-matrix th.size-col {
            min-width: 26px;
            max-width: 34px;
        }
        .size-matrix td {
            padding: 5px 3px;
            border-bottom: 1px solid #e0e0e0;
            font-size: 10px;
            vertical-align: middle;
        }
        .size-matrix td.part-cell,
        .size-matrix td.desc-cell,
        .size-matrix td.color-cell {
            text-align: left;
            padding-left: 6px;
        }
        .size-matrix td.desc-cell {
            font-size: 10px;
            max-width: 180px;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .size-matrix td.size-cell {
            text-align: center;
            font-weight: 500;
        }
        .size-matrix td.pcs-cell,
        .size-matrix td.total-cell {
            text-align: right;
            font-weight: 600;
            padding-right: 6px;
        }
        .size-matrix tr.product-row:nth-child(even) {
            background: #fafafa;
        }
        .size-matrix tr.totals-row {
            background: #f0f0f0;
            font-weight: 600;
            border-top: 2px solid #2e5827;
        }
        .size-matrix tr.totals-row td {
            padding-top: 8px;
            padding-bottom: 8px;
        }
        .size-matrix tr.extended-size-row {
            background: #f9f9f9;
        }
        .size-matrix tr.extended-size-row td {
            border-top: none;
            padding-top: 2px;
        }
        .size-matrix .unit-cell {
            font-weight: 500;
            color: #333;
        }
        .price-legend {
            font-size: 10px;
            color: #666;
            margin: 8px 0 15px 0;
            padding: 6px 10px;
            background: #f8f9fa;
            border-radius: 3px;
            border-left: 3px solid #2e5827;
        }
        @media print {
            .size-matrix tr {
                page-break-inside: avoid;
            }
        }
    `;
}

