async printWhenReady(printWindow) {
    if (!printWindow || printWindow.closed) throw new Error('The quote window was closed or blocked.');
    if (printWindow.document.readyState !== 'complete') {
        await new Promise(resolve => printWindow.addEventListener('load', resolve, { once: true }));
    }
    if (printWindow.document.fonts) await printWindow.document.fonts.ready;
    if (!printWindow.closed) printWindow.print();
}

